import{_ as a,o as d,c as e,ag as i}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"WaitWObj 等待工件位置信息","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/14. 传送带跟随指令/WaitWObj.md","filePath":"3. 指令/14. 传送带跟随指令/WaitWObj.md","lastUpdated":1778862643000}'),s={name:"3. 指令/14. 传送带跟随指令/WaitWObj.md"};function r(n,t,l,o,h,p){return d(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="waitwobj-等待工件位置信息" tabindex="-1">WaitWObj 等待工件位置信息 <a class="header-anchor" href="#waitwobj-等待工件位置信息" aria-label="Permalink to &quot;WaitWObj 等待工件位置信息&quot;">​</a></h1><p>该指令用于在指定时长内等待外部设备发来的工件在指定传送带上的位置信息。在设定时长内若等待条件满足，程序继续向下执行；若设定时长内条件未满足，则超时判断值置为 1 后，程序继续向下执行。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>WaitWObj(Coord, PieceId, T, Ret, [Goto], [Attr], [CamP])</p><p>WaitWObj(坐标系, 工件 ID, 等待时长, 超时返回值, [超时跳转标签], [视觉属性], [视觉点位])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Coord</td><td>SYNCOORD 变量</td><td>当前机器人所等待的工件位置信息所参考的动坐标系，需与传送带配置界面中启用的动坐标系一致</td><td>必填</td></tr><tr><td>PieceId</td><td>INT 变量</td><td>用来返回当前接收到的工件 id 号</td><td>必填</td></tr><tr><td>T</td><td>int</td><td>等待外部设备发来的工件位置信息的时长，单位 ms。当值为 0 时，将强制等待直到 DI 信号满足时方认为执行成功</td><td>必填</td></tr><tr><td>Ret</td><td>INT 变量</td><td>返回该指令执行结束后的状态：<br>0—成功检测到信号<br>1—未检测到信号，指令超时返回</td><td>必填</td></tr><tr><td>[Goto]</td><td>label</td><td>超时后跳转的 label 名，该 label 为在当前加载的程序中示教过的 label 指令名。等待超时后，程序指针将跳转到该标签名对应的指令行</td><td>可选，默认不跳转</td></tr><tr><td>[Attr]</td><td>INT 变量</td><td>用来返回当前接收到的物体属性值</td><td>可选</td></tr><tr><td>[CamP]</td><td>CPOS 变量</td><td>用来返回当前接收到的坐标值</td><td>可选</td></tr></tbody></table><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitWObj</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SYNCOORD0, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Goto Start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析</strong>：</p><p>在 1000ms 时长内等待与动坐标系 SYNCOORD0 绑定的传送带上外部设备发来的工件位置信息。若等到信号，程序继续向下执行；若 1000ms 内未等到条件满足，则将 INT1 置 1，同时程序指针将跳转到 &quot;Start&quot; 标签所在行开始执行。</p>',13)])])}const u=a(s,[["render",r]]);export{c as __pageData,u as default};
